import * as T from './vendor/three.module.js';
const cache={};
function resources(){if(cache.ready)return cache;cache.ready=true;
const cloth=document.createElement('canvas');cloth.width=cloth.height=256;let c=cloth.getContext('2d');c.fillStyle='#aaa';c.fillRect(0,0,256,256);for(let i=0;i<256;i+=2){c.fillStyle=i%4?'#b6b6b6':'#969696';c.fillRect(i,0,1,256);c.fillStyle='#8888';c.fillRect(0,i,256,1)}let bump=new T.CanvasTexture(cloth);bump.wrapS=bump.wrapT=T.RepeatWrapping;bump.repeat.set(3,3);
cache.tan=new T.MeshStandardMaterial({color:'#96724c',roughness:.97,bumpMap:bump,bumpScale:.006});cache.seam=new T.MeshStandardMaterial({color:'#6d573d',roughness:1});cache.white=new T.MeshStandardMaterial({color:'#dfdfd5',roughness:.93,bumpMap:bump,bumpScale:.003});cache.sole=new T.MeshStandardMaterial({color:'#c8ccca',roughness:.8});cache.skin=new T.MeshPhysicalMaterial({color:'#875634',roughness:.57,clearcoat:.08});cache.beard=new T.MeshStandardMaterial({color:'#211f1b',roughness:1});cache.gold=new T.MeshStandardMaterial({color:'#c9a554',metalness:.85,roughness:.24});cache.eye=new T.MeshStandardMaterial({color:'#d2c7b6',roughness:.4});cache.iris=new T.MeshStandardMaterial({color:'#32231b',roughness:.28});cache.lip=new T.MeshStandardMaterial({color:'#653d2b',roughness:.7});return cache}
export function makeCharacter(scene,{detail=false}={}){
const r=resources(),root=new T.Group();scene.add(root);const body=new T.Group();root.add(body);
function add(geo,mat,x,y,z,parent=body){let m=new T.Mesh(geo,mat);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function ellipsoid(rx,ry,rz,mat,x,y,z,parent=body){let m=add(new T.SphereGeometry(1,detail?24:12,detail?16:8),mat,x,y,z,parent);m.scale.set(rx,ry,rz);return m}
function capsule(radius,len,mat,x,y,z,parent=body){return add(new T.CapsuleGeometry(radius,len,6,detail?16:8),mat,x,y,z,parent)}
function bar(a,b,width,mat,parent=body){let p=new T.Vector3(...a),q=new T.Vector3(...b),d=q.clone().sub(p);let m=add(new T.CylinderGeometry(width,width,d.length(),8),mat,0,0,0,parent);m.position.copy(p.add(q).multiplyScalar(.5));m.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),d.normalize());return m}
// Tailored torso: waist, chest and sloped shoulders, rather than a cylinder.
const profile=[[.88,.205],[.94,.222],[1.08,.24],[1.25,.265],[1.36,.285],[1.42,.245],[1.46,.16]];let torso=add(new T.LatheGeometry(profile.map(([y,x])=>new T.Vector2(x,y)),32),r.tan,0,0,0);torso.scale.z=.65;
let hips=add(new T.CylinderGeometry(.21,.205,.18,24),r.tan,0,.86,0);hips.scale.z=.70;ellipsoid(.16,.29,.035,r.white,0,1.19,.164);
for(let side of [-1,1]){bar([side*.105,.94,.171],[side*.14,1.38,.171],.016,r.seam);let collar=add(new T.BoxGeometry(.10,.15,.018),r.tan,side*.11,1.42,.157);collar.rotation.z=side*.45;if(detail){let pocket=add(new T.BoxGeometry(.12,.15,.018),r.tan,side*.18,1.07,.153);pocket.rotation.z=-side*.12;bar([side*.12,1.15,.174],[side*.23,1.12,.16],.004,r.seam);bar([side*.20,.96,-.12],[side*.24,1.33,-.15],.003,r.seam)}}
bar([-.20,.94,-.11],[.20,.94,-.11],.009,r.seam);
capsule(.074,.12,r.skin,0,1.50,0);const head=new T.Group();head.position.set(0,1.69,0);body.add(head);
ellipsoid(.157,.195,.157,r.skin,0,0,0,head);ellipsoid(.127,.093,.14,r.beard,0,-.085,.034,head);ellipsoid(.121,.102,.122,r.skin,0,.016,.064,head);ellipsoid(.07,.045,.065,r.skin,0,-.045,.123,head);ellipsoid(.031,.042,.042,r.skin,0,-.006,.165,head);ellipsoid(.050,.012,.018,r.lip,0,-.067,.168,head);
for(let side of [-1,1]){ellipsoid(.028,.05,.025,r.skin,side*.151,-.008,0,head);ellipsoid(.039,.021,.016,r.eye,side*.058,.045,.139,head);ellipsoid(.014,.015,.009,r.iris,side*.058,.045,.155,head);let brow=add(new T.BoxGeometry(.063,.015,.014),r.beard,side*.059,.077,.139,head);brow.rotation.z=side*.09;ellipsoid(.011,.011,.007,r.gold,side*.173,-.035,.012,head);if(detail){ellipsoid(.05,.018,.014,r.skin,side*.06,.067,.139,head);bar([side*.035,.031,.151],[side*.09,.031,.139],.003,r.skin,head)}}
let chain=add(new T.TorusGeometry(.118,.006,6,40,Math.PI),r.gold,0,1.39,.185);chain.rotation.z=Math.PI;add(new T.BoxGeometry(.021,.032,.008),r.gold,0,1.27,.198);
const arms=[],legs=[];for(let side of [-1,1]){const upper=new T.Group();upper.position.set(side*.275,1.37,0);upper.rotation.z=side*.08;body.add(upper);ellipsoid(.104,.14,.11,r.tan,0,-.04,0,upper);capsule(.085,.20,r.tan,0,-.185,0,upper);const lower=new T.Group();lower.position.set(0,-.35,0);upper.add(lower);capsule(.074,.18,r.tan,0,-.145,0,lower);capsule(.073,.015,r.seam,0,-.26,0,lower);ellipsoid(.056,.085,.039,r.skin,0,-.355,.006,lower);if(detail){for(let f=0;f<4;f++){let finger=capsule(.009,.052,r.skin,-.032+f*.021,-.408,.014,lower);finger.rotation.x=-.12}let thumb=capsule(.013,.045,r.skin,side*.052,-.35,.017,lower);thumb.rotation.z=-side*.4}arms.push({upper,lower});
const thigh=new T.Group();thigh.position.set(side*.115,.88,0);root.add(thigh);capsule(.108,.22,r.tan,0,-.21,0,thigh);const knee=new T.Group();knee.position.set(0,-.43,0);thigh.add(knee);capsule(.095,.23,r.tan,0,-.16,0,knee);capsule(.084,.018,r.seam,0,-.335,0,knee);const foot=new T.Group();foot.position.set(0,-.37,.045);knee.add(foot);ellipsoid(.105,.075,.185,r.white,0,-.005,.035,foot);let sole=add(new T.BoxGeometry(.205,.025,.32),r.sole,0,-.062,.04,foot);if(detail){for(let j=0;j<4;j++)bar([-.06,.045,-.015+j*.026],[.06,.045,-.015+j*.026],.004,r.sole,foot);bar([side*.104,-.01,-.04],[side*.104,.01,.11],.005,r.sole,foot);bar([side*.09,-.16,-.005],[side*.09,-.32,-.005],.003,r.seam,knee)}legs.push({thigh,knee,foot});}
const shadow=add(new T.CircleGeometry(.34,32),new T.MeshBasicMaterial({color:'#15201a',transparent:true,opacity:.13,depthWrite:false}),0,.077,0,root);shadow.rotation.x=-Math.PI/2;
let gait=0,previous=0,blend=0;return{root,update(time,moving,running){let dt=Math.min(.05,Math.max(.001,time-previous));previous=time;blend=T.MathUtils.damp(blend,moving?1:0,9,dt);gait+=dt*(running?11:7);let a=Math.sin(gait),b=Math.sin(gait+Math.PI),amp=running?.78:.42;for(let i=0;i<2;i++){let s=i?b:a;legs[i].thigh.rotation.x=s*amp*blend;legs[i].knee.rotation.x=-Math.max(0,-s)*(running?1.15:.65)*blend;legs[i].foot.rotation.x=-legs[i].thigh.rotation.x*.3-legs[i].knee.rotation.x*.45;arms[i].upper.rotation.x=-s*(running?.72:.35)*blend;arms[i].lower.rotation.x=-(.12+(running?.8:.1)*blend)}body.position.y=Math.abs(Math.sin(gait*2))*.022*blend;body.rotation.z=a*.025*blend;body.rotation.y=a*.045*blend;head.rotation.y=-a*.025*blend;body.rotation.x=running?.10*blend:0}};
}
